function selectObject(id){if(!touchLayout()){go(id);return;}if(S.mode!=='world'||S.ending)return;const o=objects.find(o=>o.id===id);S.target=null;mobileSelection=id;const canTalk=['client','spouse'].includes(id);const canUse=!['lamp'].includes(id);const verbs=['look',...(canTalk?['talk']:[]),...(canUse?['use']:[])];let label=id==='client'&&S.has?'Entregar expediente':id==='sheet'?'Recoger':id==='exit'||id==='door'||id==='bedroom'?'Ir':id==='bed'?'Acostarte':id==='spouse'?'Hablar': 'Usar';if(id==='spouse')verbs.splice(verbs.indexOf('use'),1);speak(o.name,'¿Qué quieres hacer?',verbs.map(v=>[v==='look'?'Mirar':v==='talk'?'Hablar':label,'']));choiceHandler=i=>{S.verb=verbs[i];go(id);};document.querySelectorAll('[data-object]').forEach(b=>b.classList.toggle('selected-object',b.dataset.object===id));}
function setPanel(open){document.body.classList.toggle('panel-open',open);const b=document.getElementById('panel-toggle');if(b){b.textContent=open?'Ver escena':'Acciones';b.setAttribute('aria-expanded',String(open));}}
